{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2150-07-23 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning, Ms. ___ . I’m Dr. ___ . I understand you had a fall yesterday. Can you tell me what happened?"
    },
    {
      "turn_number": 2,
      "time": "2150-07-23 07:01:00",
      "speaker": "Patient",
      "text": "Yes, I was standing on my bathroom scale and when I turned to step off, I lost my balance and fell. I couldn’t get up, so I called for help."
    },
    {
      "turn_number": 3,
      "time": "2150-07-23 07:02:00",
      "speaker": "Doctor",
      "text": "I see. Did you hit your head or lose consciousness?"
    },
    {
      "turn_number": 4,
      "time": "2150-07-23 07:02:30",
      "speaker": "Patient",
      "text": "No, I didn’t black out or wet myself. I just landed on my left hip and it’s been sore and bruised since."
    },
    {
      "turn_number": 5,
      "time": "2150-07-23 07:03:15",
      "speaker": "Doctor",
      "text": "And you mentioned this wasn’t your first fall recently?"
    },
    {
      "turn_number": 6,
      "time": "2150-07-23 07:04:00",
      "speaker": "Patient",
      "text": "No, the day before, I fell while trying to put on my shoes. Same hip. I’ve had a few in the past few weeks, but nothing serious until now."
    },
    {
      "turn_number": 7,
      "time": "2150-07-23 07:05:00",
      "speaker": "Doctor",
      "text": "Thank you. We’ve reviewed your tests. Your CT head showed no bleeding or fracture, which is good."
    },
    {
      "turn_number": 8,
      "time": "2150-07-23 07:05:45",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried about that."
    },
    {
      "turn_number": 9,
      "time": "2150-07-23 07:06:30",
      "speaker": "Doctor",
      "text": "We also did a CT of your abdomen and pelvis. It shows several hematomas on your left hip and thigh from the fall."
    },
    {
      "turn_number": 10,
      "time": "2150-07-23 07:07:15",
      "speaker": "Patient",
      "text": "So that’s why it’s so swollen and discolored?"
    },
    {
      "turn_number": 11,
      "time": "2150-07-23 07:07:45",
      "speaker": "Doctor",
      "text": "Exactly. The bruising is from bleeding into the soft tissue. We’re watching your blood counts closely because of it."
    },
    {
      "turn_number": 12,
      "time": "2150-07-23 07:08:30",
      "speaker": "Patient",
      "text": "My hemoglobin was low last time I was here too. Is it bad again?"
    },
    {
      "turn_number": 13,
      "time": "2150-07-23 07:09:15",
      "speaker": "Doctor",
      "text": "It’s 8.8 now, which is lower than your usual 10.5. We’ll keep an eye on it. No need for transfusion yet."
    },
    {
      "turn_number": 14,
      "time": "2150-07-23 07:10:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense."
    },
    {
      "turn_number": 15,
      "time": "2150-07-23 07:10:30",
      "speaker": "Doctor",
      "text": "We also checked your heart. Your EKG was normal, and your troponin levels were negative. No sign of a heart attack."
    },
    {
      "turn_number": 16,
      "time": "2150-07-23 07:11:15",
      "speaker": "Patient",
      "text": "I’ve been feeling some palpitations lately, but no chest pain."
    },
    {
      "turn_number": 17,
      "time": "2150-07-23 07:12:00",
      "speaker": "Doctor",
      "text": "We’re monitoring you on telemetry. So far, no arrhythmias. The palpitations may be related to your heart condition, but nothing urgent now."
    },
    {
      "turn_number": 18,
      "time": "2150-07-23 07:13:00",
      "speaker": "Patient",
      "text": "I had that NSTEMI a few months ago. Is my heart still okay?"
    },
    {
      "turn_number": 19,
      "time": "2150-07-23 07:13:45",
      "speaker": "Doctor",
      "text": "Yes, your heart function is stable. EF is still 60%. We’re continuing your usual heart meds."
    },
    {
      "turn_number": 20,
      "time": "2150-07-23 07:14:30",
      "speaker": "Patient",
      "text": "Good. And my aortic dissection repair—is that okay?"
    },
    {
      "turn_number": 21,
      "time": "2150-07-23 07:15:15",
      "speaker": "Doctor",
      "text": "The CT shows no new issues with your repair. But we can’t fully assess it without contrast. We’ll consider a contrast CT later as an outpatient."
    },
    {
      "turn_number": 22,
      "time": "2150-07-23 07:16:00",
      "speaker": "Patient",
      "text": "I remember I can’t have IV dye because of my allergy."
    },
    {
      "turn_number": 23,
      "time": "2150-07-23 07:16:30",
      "speaker": "Doctor",
      "text": "That’s right. We’ll plan carefully if we need that scan later."
    },
    {
      "turn_number": 24,
      "time": "2150-07-23 07:17:15",
      "speaker": "Patient",
      "text": "Okay, thanks."
    },
    {
      "turn_number": 25,
      "time": "2150-07-24 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs this morning show your hemoglobin dropped to 7.3. We’d like to give you one unit of blood to help it recover."
    },
    {
      "turn_number": 26,
      "time": "2150-07-24 08:01:00",
      "speaker": "Patient",
      "text": "Is that safe with my platelet issue?"
    },
    {
      "turn_number": 27,
      "time": "2150-07-24 08:02:00",
      "speaker": "Doctor",
      "text": "Yes, your platelets are stable at 102,000. It’s safe to transfuse. We’ll monitor you closely."
    },
    {
      "turn_number": 28,
      "time": "2150-07-24 08:03:00",
      "speaker": "Patient",
      "text": "Alright, I trust you."
    },
    {
      "turn_number": 29,
      "time": "2150-07-24 09:30:00",
      "speaker": "Doctor",
      "text": "The transfusion went well. Your hemoglobin is now 8.3. That’s a good response."
    },
    {
      "turn_number": 30,
      "time": "2150-07-24 09:31:00",
      "speaker": "Patient",
      "text": "I feel a bit stronger already."
    },
    {
      "turn_number": 31,
      "time": "2150-07-24 09:32:00",
      "speaker": "Doctor",
      "text": "Great. Physical therapy saw you this morning. They say you can walk with help, but you’ll need rehab to build strength."
    },
    {
      "turn_number": 32,
      "time": "2150-07-24 09:33:00",
      "speaker": "Patient",
      "text": "I’ve been unsteady lately. I think rehab will help."
    },
    {
      "turn_number": 33,
      "time": "2150-07-24 09:34:00",
      "speaker": "Doctor",
      "text": "Yes, especially since you’ve had multiple falls. We want to prevent another one."
    },
    {
      "turn_number": 34,
      "time": "2150-07-24 09:35:00",
      "speaker": "Patient",
      "text": "I do too. My son’s worried."
    },
    {
      "turn_number": 35,
      "time": "2150-07-24 10:00:00",
      "speaker": "Doctor",
      "text": "One more thing—your white blood cell count is high, but we don’t think it’s infection. Likely a reaction to the bruising."
    },
    {
      "turn_number": 36,
      "time": "2150-07-24 10:01:00",
      "speaker": "Patient",
      "text": "So no antibiotics?"
    },
    {
      "turn_number": 37,
      "time": "2150-07-24 10:01:30",
      "speaker": "Doctor",
      "text": "Not right now. We’ll keep watching."
    },
    {
      "turn_number": 38,
      "time": "2150-07-25 08:15:00",
      "speaker": "Doctor",
      "text": "Good news—your labs are stable. Hemoglobin is holding at 8.3, and kidney function is okay."
    },
    {
      "turn_number": 39,
      "time": "2150-07-25 08:16:00",
      "speaker": "Patient",
      "text": "That’s good. When can I go to rehab?"
    },
    {
      "turn_number": 40,
      "time": "2150-07-25 08:17:00",
      "speaker": "Doctor",
      "text": "We’re arranging discharge tomorrow. You’ll go to an extended care facility for rehab."
    },
    {
      "turn_number": 41,
      "time": "2150-07-25 08:18:00",
      "speaker": "Patient",
      "text": "I’m ready to get stronger. What about my meds?"
    },
    {
      "turn_number": 42,
      "time": "2150-07-25 08:19:00",
      "speaker": "Doctor",
      "text": "Most stay the same. We’re lowering your allopurinol from 150 mg to 100 mg because of your kidney function."
    },
    {
      "turn_number": 43,
      "time": "2150-07-25 08:20:00",
      "speaker": "Patient",
      "text": "For my gout, right?"
    },
    {
      "turn_number": 44,
      "time": "2150-07-25 08:20:30",
      "speaker": "Doctor",
      "text": "Yes. It’s safer at this dose with your creatinine."
    },
    {
      "turn_number": 45,
      "time": "2150-07-25 08:21:15",
      "speaker": "Patient",
      "text": "Got it."
    },
    {
      "turn_number": 46,
      "time": "2150-07-26 09:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. You’re being discharged to rehab. How are you feeling?"
    },
    {
      "turn_number": 47,
      "time": "2150-07-26 09:01:00",
      "speaker": "Patient",
      "text": "A bit sore, but ready to go. Thank you for taking care of me."
    },
    {
      "turn_number": 48,
      "time": "2150-07-26 09:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember: take all your meds, especially the new allopurinol dose."
    },
    {
      "turn_number": 49,
      "time": "2150-07-26 09:03:00",
      "speaker": "Patient",
      "text": "I will. And keep doing PT?"
    },
    {
      "turn_number": 50,
      "time": "2150-07-26 09:03:30",
      "speaker": "Doctor",
      "text": "Exactly. Also, weigh yourself daily. Call your doctor if you gain more than 3 pounds."
    },
    {
      "turn_number": 51,
      "time": "2150-07-26 09:04:15",
      "speaker": "Patient",
      "text": "I’ll do that. And follow up with my cardiologist?"
    },
    {
      "turn_number": 52,
      "time": "2150-07-26 09:05:00",
      "speaker": "Doctor",
      "text": "Yes, and we’ll schedule that CT of your chest with contrast as an outpatient, when safe."
    },
    {
      "turn_number": 53,
      "time": "2150-07-26 09:06:00",
      "speaker": "Patient",
      "text": "I’ll make sure to keep that appointment."
    },
    {
      "turn_number": 54,
      "time": "2150-07-26 09:07:00",
      "speaker": "Doctor",
      "text": "One last thing—your code status is DNR/DNI. That’s still correct?"
    },
    {
      "turn_number": 55,
      "time": "2150-07-26 09:07:45",
      "speaker": "Patient",
      "text": "Yes, that’s right. I don’t want resuscitation."
    },
    {
      "turn_number": 56,
      "time": "2150-07-26 09:08:30",
      "speaker": "Doctor",
      "text": "Noted. Your son is listed as contact. We’ll send all info to him too."
    },
    {
      "turn_number": 57,
      "time": "2150-07-26 09:09:15",
      "speaker": "Patient",
      "text": "He’ll help me keep track."
    },
    {
      "turn_number": 58,
      "time": "2150-07-26 09:10:00",
      "speaker": "Doctor",
      "text": "Perfect. The transport team will take you to rehab in about an hour."
    },
    {
      "turn_number": 59,
      "time": "2150-07-26 09:10:45",
      "speaker": "Patient",
      "text": "I’m ready. Thank you again, Doctor."
    },
    {
      "turn_number": 60,
      "time": "2150-07-26 09:11:30",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you in follow-up if needed."
    }
  ],
  "summary": {
    "admission_start": "2150-07-23 06:39:00",
    "admission_end": "2150-07-26 18:21:00",
    "summary_paragraph": "A 68-year-old woman was admitted after a mechanical fall at home, landing on her left hip. She had multiple recent falls and presented with a large left hip hematoma. Imaging showed no fractures but confirmed soft tissue hematomas. Her hemoglobin dropped from 8.8 to 7.3, prompting a single unit red blood cell transfusion. Cardiac workup was negative for acute ischemia, and telemetry showed no arrhythmias. She remained stable, with no signs of infection despite leukocytosis. Physical therapy recommended inpatient rehabilitation for strength and fall prevention. She was discharged to an extended care facility with continued heart failure management, a reduced allopurinol dose for renal protection, and plans for outpatient follow-up including a contrast CT of the chest to evaluate aortic arch dilation.",
    "problems": [
      "Contusion of left hip, initial encounter",
      "Chronic diastolic (congestive) heart failure",
      "Acute posthemorrhagic anemia",
      "Atherosclerotic heart disease of native coronary artery without angina pectoris",
      "Presence of coronary angioplasty implant and graft",
      "Old myocardial infarction",
      "Gastro-esophageal reflux disease without esophagitis",
      "Personal history of malignant neoplasm of breast",
      "History of falling",
      "Essential (primary) hypertension",
      "Unspecified fall, initial encounter",
      "Elevated white blood cell count, unspecified",
      "Major depressive disorder, single episode, unspecified",
      "Gout, unspecified",
      "Do not resuscitate"
    ]
  }
}
